/* Whether this machine can make a complex operation, and what each machine does with a level-11 mission. Pure
 * decisions, with no game or loader state of their own, so the tests can ask every case.
 *
 * A complex operation is generated by every peer from the host's seed. A peer that cannot generate one must never be in
 * a mission that is one, and no peer may guess what the host decided: the host says so in one row of the shared table,
 * and a peer without the answer leaves instead of assuming one. */
#include "co.h"

/* Why the complex part is off, or NULL when it is on. The order is the order a player can act on: HellForge first. */
const char* co_complex_refusal(const CoComplexNeeds* n)
{
    if (!n->capacity_call) return "this HellForge has no generation_capacity: update HellForge";
    if (!n->regions) return "this HellForge does not report the map generator's layout: update HellForge";
    if (n->live_load) return "the mod was loaded while the game ran: restart the game";
    if (!n->capacity_granted) return "HellForge refused the map generator's capacity (its log line says why)";
    if (!n->level_11) return "difficulty 11 is not installed (the Hell Forge mod is off or failed)";
    if (!n->moved) return "the map generator kept its own arrays";
    if (!n->stock_stubs) return "difficulty 11's larger-map steps are not the ones this mod was built for";
    if (!n->own_sites) return "the game's code is not the build this mod was made for";
    if (n->commit_free_mb < CO_COMPLEX_COMMIT_MB) return "not enough memory free for an extra large map";
    return NULL;
}

/* What a machine does at a level-11 mission: `host_row` is the host's answer as this machine holds it. */
int co_complex_decision(int is_host, int own_on, int host_row, uint32_t mission_seed)
{
    int marked = co_seed_is_complex(mission_seed);
    if (is_host) return own_on && marked ? CO_MISSION_COMPLEX : CO_MISSION_NORMAL;
    if (host_row == CO_HOST_ROW_NONE) return CO_MISSION_LEAVE;
    if (host_row == CO_HOST_ROW_OFF) return CO_MISSION_NORMAL;
    if (!own_on) return CO_MISSION_LEAVE;
    return marked ? CO_MISSION_COMPLEX : CO_MISSION_NORMAL;
}

/* Whether a client stays in a session, asked when the host's row arrives or changes: a machine that cannot make a
 * complex operation goes before a mission can start. */
int co_complex_stays(int own_on, int host_row) { return own_on || host_row != CO_HOST_ROW_ON; }

int co_complex_rolls(int is_host, int own_on, int host_row) { return is_host ? own_on != 0 : host_row == CO_HOST_ROW_ON; }

/* The seed a mission entry keeps: other levels' as the game made it; level 11's with the decision. Only a host whose
 * complex part is on rolls; a client marks its own board the same way for its war table when the host's row says on. */
uint32_t co_complex_entry_seed(uint32_t mission_seed, uint32_t difficulty, uint32_t operation_seed, uint32_t planet, int rolls)
{
    if (difficulty != CO_COMPLEX_LEVEL) return mission_seed;
    return co_seed_marked(mission_seed, rolls && co_complex_roll(operation_seed, planet, CO_COMPLEX_CHANCE));
}
